float get_base_load(uint16_t index) {
    if(index < BASE_LOAD_SIZE) {
        return base_load_data[index];
    }
    return 0.0f;
}

float get_lmp_price(uint16_t index) {
    if(index < LMP_PRICE_SIZE) {
        return lmp_price_data[index];
    }
    return 0.0f;
}

float get_pv_generation(uint16_t index) {
    if(index < PV_GENERATION_SIZE) {
        return pv_generation_data[index];
    }
    return 0.0f;
}

EV_Info get_ev_info(uint16_t ev_id) {
    EV_Info default_info = {0, 0, 0, 0, 0.0f, 0.0f};
    
    if(ev_id < EV_DATA_COUNT) {
        return ev_data[ev_id];
    }
    return default_info;
}

uint16_t get_ev_count(void) {
    return EV_DATA_COUNT;
}
